  'vector.distModelResp': { 'zh-CN': '向量模型 (Embedding API): 负责语义搜索 (search_knowledge)、文本嵌入 (embed_text)、语义比较 (compare_texts)', 'en-US': 'Vector Model (Embedding API): handles semantic search (search_knowledge), text embedding (embed_text), semantic comparison (compare_texts)', 'ru-RU': 'Векторная модель (Embedding API): семантический поиск (search_knowledge), эмбеддинг текста (embed_text), семантическое сравнение (compare_texts)' },
  'vector.distLLMResp': { 'zh-CN': 'LLM 向量化: 使用 LLM 生成语义向量，作为 Embedding API 的补充或替代方案。当 Embedding API 不可用时自动接管', 'en-US': 'LLM Vectorization: generates semantic vectors using LLM, serves as supplement or alternative to Embedding API. Automatically takes over when Embedding API is unavailable', 'ru-RU': 'Векторизация LLM: генерация семантических векторов через LLM, дополнение или замена Embedding API. Автоматически перехватывает управление при недоступности Embedding API' },
  'vector.distModuleResp': { 'zh-CN': '本地模块 (LanceDB): 负责 FTS 全文搜索、快速文本匹配、本地相似度验证', 'en-US': 'Local Module (LanceDB): handles FTS full-text search, fast text matching, local similarity verification', 'ru-RU': 'Локальный модуль (LanceDB): полнотекстовый поиск FTS, быстрое сопоставление, локальная проверка схожести' },
  'vector.distChainLLM': { 'zh-CN': '降级链: Embedding API → LLM 向量化 → 本地 FTS', 'en-US': 'Fallback chain: Embedding API → LLM Vectorization → Local FTS', 'ru-RU': 'Цепочка отказоустойчивости: Embedding API → Векторизация LLM → Локальный FTS' },
